mapper.select:

where del_flag = '0'
and id != #{id}
and big_roll_code is null
and big_roll_code = #{bigRollCode}

mapper.update:
merge into t_gdyy_quota_setting a USING (
select #{QuotaSetting.bigRollCode,jdbcType=VARCHAR} big_roll_code, #{QuotaSetting.quota,jdbcType=DOUBLE} quota, #{QuotaSetting.createBy,jdbcType=VARCHAR} create_by, #{QuotaSetting.createTime,jdbcType=DATE} create_time, #{QuotaSetting.updateBy,jdbcType=VARCHAR} update_by, #{QuotaSetting.updateTime,jdbcType=DATE} update_time, #{QuotaSetting.remark,jdbcType=VARCHAR} remark from dual
) b ON ( ((b.big_roll_code is null and a.big_roll_code is null) or (a.big_roll_code = b.big_roll_code)) AND a.del_flag = '0' ) WHEN MATCHED THEN UPDATE SET a.quota = b.quota, a.update_by = b.create_by, a.update_time = sysdate, a.remark = b.remark WHEN NOT MATCHED THEN INSERT (a.id, a.big_roll_code, a.quota, a.create_by, a.create_time, a.remark, a.del_flag) values (SEQ_QUOTA_SETTING.NEXTVAL, b.big_roll_code, b.quota, b.create_by, sysdate, b.remark, '0')
